using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net;
using System.Security.Cryptography;
using System.Text;
class TickHistory {
 public string Status {get;private set;}
 public TickHistory(){Status="尚未回補歷史逐筆；本機累積不代表完整一週";}
 static string Hash(string file){using(var stream=File.OpenRead(file))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
 static string Header(Stream stream,out Encoding encoding){var bytes=new List<byte>();int c;while((c=stream.ReadByte())>=0){if(c==10)break;if(bytes.Count>16384)throw new InvalidDataException("CSV 標頭過長");bytes.Add((byte)c);}try{encoding=new UTF8Encoding(false,true);return encoding.GetString(bytes.ToArray()).TrimEnd('\r');}catch(DecoderFallbackException){encoding=Encoding.GetEncoding(950);return encoding.GetString(bytes.ToArray()).TrimEnd('\r');}}
 public int Import(string file,string month,MarketArchive target,string source){var temp=new MarketArchive(null);string feed="history:"+Hash(file);int count=0,entryId=0;if(file.EndsWith(".zip",StringComparison.OrdinalIgnoreCase)){using(var zip=ZipFile.OpenRead(file)){foreach(var entry in zip.Entries){if(!entry.FullName.EndsWith(".csv",StringComparison.OrdinalIgnoreCase))continue;if(entry.Length>512L*1024*1024)throw new InvalidDataException("逐筆 CSV 超過 512 MB 限制");using(var stream=entry.Open())count+=Read(stream,month,temp,feed+":"+(entryId++));}}}else{if(new FileInfo(file).Length>512L*1024*1024)throw new InvalidDataException("逐筆 CSV 超過 512 MB 限制");using(var stream=File.OpenRead(file))count=Read(stream,month,temp,feed);}if(count==0)throw new InvalidDataException("沒有當月單式台指期／選擇權逐筆；請核對檔案與月份");target.ImportHistorical(temp,source);Status="已回補 "+count+" 筆；覆蓋範圍依來源檔，主動方因缺委託報價維持未明";return count;}
 int Read(Stream stream,string month,MarketArchive target,string feed){Encoding encoding;var h=MarketCsv.Headers(Header(stream,out encoding));int date=MarketCsv.Index(h,"成交日期"),code=MarketCsv.Index(h,"商品代號","契約"),maturity=MarketCsv.Index(h,"到期月份(週別)"),time=MarketCsv.Index(h,"成交時間"),price=MarketCsv.Index(h,"成交價格","成交價"),qty=MarketCsv.Index(h,"成交數量(B+S)","成交數量"),strike=MarketCsv.Index(h,"履約價格","履約價"),cp=MarketCsv.Index(h,"買賣權別","買賣權");if(date<0||code<0||maturity<0||time<0||price<0||qty<0)throw new InvalidDataException("逐筆 CSV 標頭不符，未回補");bool doubled=h.ContainsKey("成交數量(B+S)");int count=0,lineNo=0;using(var reader=new StreamReader(stream,encoding,false,8192,true)){string line;while((line=reader.ReadLine())!=null){lineNo++;if(line.Length>16384)throw new InvalidDataException("逐筆列過長");var row=MarketCsv.Row(line);if(MarketCsv.Cell(row,maturity)!=month)continue;string product=MarketCsv.Cell(row,code).ToUpperInvariant(),prefix=MarketCsv.Future(product),side=MarketCsv.OptionSide(MarketCsv.Cell(row,cp).ToUpperInvariant());double k=MarketCsv.Number(MarketCsv.Cell(row,strike))??0;if(prefix==null&&(product!="TXO"||side==null||k<=0))continue;double? p=MarketCsv.Number(MarketCsv.Cell(row,price)),q=MarketCsv.Number(MarketCsv.Cell(row,qty));if(!p.HasValue||p<=0||!q.HasValue||q<=0||q!=Math.Truncate(q.Value)||q>int.MaxValue)throw new InvalidDataException("逐筆價格或口數無法辨識");int lots=(int)q.Value;if(doubled){if(lots%2!=0)throw new InvalidDataException("B+S 數量不是偶數，不能換算成成交口數");lots/=2;}DateTime d=MarketCsv.Date(MarketCsv.Cell(row,date)),clock;if(!DateTime.TryParseExact(MarketCsv.Cell(row,time),new[]{"HHmmss","HHmmssfff","HHmmssffffff","HH:mm:ss","HH:mm:ss.fff"},CultureInfo.InvariantCulture,DateTimeStyles.None,out clock))throw new InvalidDataException("逐筆時間格式不符");long utc=MarketSessions.Utc(d.Add(clock.TimeOfDay));string symbol=prefix!=null?MonthlyContract.SymbolFor(prefix,month):MarketCsv.OptionSymbol(month,k,side);double multiplier=prefix=="TXF"?200:prefix=="MXF"?50:prefix=="TMF"?10:50;target.Trade(symbol,prefix!=null?"future":side,k,p.Value,lots,"unknown",utc,multiplier,feed,lineNo);count++;}}return count;}
 public int Download(DateTime taipei,string month,MarketArchive target){int total=0;var missing=new List<string>();for(int back=7;back>=1;back--){var date=taipei.Date.AddDays(-back);foreach(bool option in new[]{false,true}){string name=(option?"OptionsDaily_":"Daily_")+date.ToString("yyyy_MM_dd")+".zip",temp=Path.Combine(Path.GetTempPath(),"tanyasite-"+Guid.NewGuid().ToString("N")+".zip");try{Status="逐筆回補中："+name+"；即時行情繼續接收";ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create("https://www.taifex.com.tw/file/taifex/Dailydownload/DailydownloadCSV/"+name);request.Timeout=30000;request.ReadWriteTimeout=30000;request.UserAgent="TanyaSiteMarketHistory/1.0";using(var response=request.GetResponse())using(var input=response.GetResponseStream())using(var output=File.Create(temp)){var buffer=new byte[65536];int n;while((n=input.Read(buffer,0,buffer.Length))>0){output.Write(buffer,0,n);if(output.Length>128L*1024*1024)throw new InvalidDataException("逐筆壓縮檔超過 128 MB 限制");}}total+=Import(temp,month,target,"期交所日逐筆檔（成交日期／時間）");}catch(Exception ex){missing.Add(name+":"+ex.GetType().Name);}finally{try{if(File.Exists(temp))File.Delete(temp);}catch(IOException){}}}}Status=missing.Count>0?"逐筆回補 "+total+" 筆；"+missing.Count+" 個來源未取得（休市、未公布或連線／格式問題），不宣稱完整一週":"逐筆回補完成；請核對日期與涵蓋商品";return total;}
}
